#include "../../../../kelly-slaters-pro-surfer/KS/SRC/ks/global.h"
#include "../../../../kelly-slaters-pro-surfer/KS/SRC/ks/FrontEndMenus.h"

void GoalsMenuClass::Draw()
{
	title->Draw();
	for (int g = 0; g < MAX_GOALS_PER_LEVEL; g++)
	{
		names[g]->Draw();
		status[g]->Draw();
	}
	helpText->Draw();

	if(show_tip)
	{
		for(int i=0; i<9; i++)
			tip_box[i]->Draw(0);
		tip->Draw();
	}
}
